class Solution:
    def countMajoritySubarrays(self, nums: list[int], target: int) -> int:
        # Transform: target -> +1, others -> -1
        # Subarray has target as majority iff sum > 0
        n = len(nums)
        ans = 0
        for i in range(n):
            cur = 0
            for j in range(i, n):
                cur += 1 if nums[j] == target else -1
                if cur > 0:
                    ans += 1
        return ans
