#include <vector>
using namespace std;

class Solution {
public:
    int countMajoritySubarrays(vector<int>& nums, int target) {
        int n = nums.size();
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            int cur = 0;
            for (int j = i; j < n; ++j) {
                cur += (nums[j] == target) ? 1 : -1;
                if (cur > 0) ans++;
            }
        }
        return ans;
    }
};

