var countMajoritySubarrays = function(nums, target) {
    const n = nums.length;
    let ans = 0;
    for (let i = 0; i < n; i++) {
        let cur = 0;
        for (let j = i; j < n; j++) {
            cur += (nums[j] === target) ? 1 : -1;
            if (cur > 0) ans++;
        }
    }
    return ans;
